    /// Connects a model to a port: subscribes every state stream and builds the model from their replayed values,
    /// then subscribes the lists and event streams (a list's replay arrives before this returns). A state stream
    /// that replays nothing is a contract defect.
    public static func connect(_ port: OahuPort) throws -> IdentitySectionModel {
        try connect(OahuConnection(port: port))
    }

    /// `connect(_:)` over a connection you made.
    public static func connect(_ connection: OahuConnection) throws -> IdentitySectionModel {
        // Each stream decodes a whole message in `read`; the connection checks every byte was read, and only then is
        // the value applied (to the model, if it is still there). A bad message leaves every value unchanged, though
        // observers may see one change notification for it.
        let copySubscription = connection.subscribeState(
            IdentitySectionContract.Stream.copy,
            read: IdentitySectionCopy.read)
        let titleSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.title,
            read: { Int(try $0.readInt()) })
        let firstNameSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.firstName,
            read: { try $0.readString() })
        let middleNameSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.middleName,
            read: { try $0.readString() })
        let lastNameSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.lastName,
            read: { try $0.readString() })
        let usernameSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.username,
            read: { try $0.readString() })
        let companySubscription = connection.subscribeState(
            IdentitySectionContract.Stream.company,
            read: { try $0.readString() })
        let ssnSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.ssn,
            read: { try $0.readString() })
        let passportNumberSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.passportNumber,
            read: { try $0.readString() })
        let licenseNumberSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.licenseNumber,
            read: { try $0.readString() })
        let emailSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.email,
            read: { try $0.readString() })
        let phoneSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.phone,
            read: { try $0.readString() })
        let address1Subscription = connection.subscribeState(
            IdentitySectionContract.Stream.address1,
            read: { try $0.readString() })
        let address2Subscription = connection.subscribeState(
            IdentitySectionContract.Stream.address2,
            read: { try $0.readString() })
        let address3Subscription = connection.subscribeState(
            IdentitySectionContract.Stream.address3,
            read: { try $0.readString() })
        let citySubscription = connection.subscribeState(
            IdentitySectionContract.Stream.city,
            read: { try $0.readString() })
        let stateSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.state,
            read: { try $0.readString() })
        let postalCodeSubscription = connection.subscribeState(
            IdentitySectionContract.Stream.postalCode,
            read: { try $0.readString() })
        let countrySubscription = connection.subscribeState(
            IdentitySectionContract.Stream.country,
            read: { try $0.readString() })
        let model: IdentitySectionModel
        do {
            model = IdentitySectionModel(
                connection: connection,
                copy: try copySubscription.initialValue(),
                title: try titleSubscription.initialValue(),
                firstName: try firstNameSubscription.initialValue(),
                middleName: try middleNameSubscription.initialValue(),
                lastName: try lastNameSubscription.initialValue(),
                username: try usernameSubscription.initialValue(),
                company: try companySubscription.initialValue(),
                ssn: try ssnSubscription.initialValue(),
                passportNumber: try passportNumberSubscription.initialValue(),
                licenseNumber: try licenseNumberSubscription.initialValue(),
                email: try emailSubscription.initialValue(),
                phone: try phoneSubscription.initialValue(),
                address1: try address1Subscription.initialValue(),
                address2: try address2Subscription.initialValue(),
