// MARK: - Screen provider

@objc(OAHUScreen_ed724fb218409b8fd4501641985fb2d0edd488e759e3b48414c4def73bce0e0f)
public final class IdentitySectionScreenProvider: NSObject, ScreenProvider {
    private static let log = Logger(subsystem: "OahuRuntime", category: "screens")

    public func contractHash(_ contract: String) -> Int64 {
        contract == IdentitySectionContract.name ? IdentitySectionContract.hash : 0
    }

    public func createScreen(_ contract: String, hash: Int64, port: OahuPort) -> ScreenHandle? {
        guard contract == IdentitySectionContract.name else { return nil }
        guard hash == IdentitySectionContract.hash, port.contractHash == hash, port.contractName == contract else {
            Self.log.error("Refusing \(contract, privacy: .public): the port's hash is \(port.contractHash), this library was built against \(IdentitySectionContract.hash)")
            return nil
        }
        let model: IdentitySectionModel
        do {
            model = try IdentitySectionModel.connect(port)
        } catch {
            Self.log.error("IdentitySection could not connect: \(error, privacy: .public)")
            return nil
        }
        return OahuScreen(rootView: IdentitySectionScreen(model: model)) { model.close() }
    }
}
